void dei_rf_usr_irq( void )
{
    if( dei_rf.tx_complete )
    {
        dei_rf.tx_complete = FALSE ; 
            
        TRACE_DEI_RF("\n\r[LIB.DEI_RF] TX COMPLETE\n\r");             

        os_irq_set_i( dei_rf.tx_irq ) ;
    };

    if( dei_rf.rx_complete )
    {
        dei_rf.rx_complete = FALSE ; 
            
        TRACE_DEI_RF("\n\r[LIB.DEI_RF] RX COMPLETE\n\r");             

        os_irq_set_i( dei_rf.rx_irq ) ;
    };

        
}

